?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Checkout | MobiVibe.lk</title><link rel="stylesheet" href="style.css"><style>.checkout-wrap{max-width:900px;margin:35px auto;padding:0 18px}.checkout-grid{display:grid;grid-template-columns:1fr 1fr;gap:22px}.checkout-card{padding:22px;background:#fff;border:1px solid #e5e7eb;border-radius:12px}.checkout-card input,.checkout-card textarea{width:100%;padding:12px;border:1px solid #ccd0d8;border-radius:7px;margin:6px 0 14px}@media(max-width:700px){.checkout-grid{grid-template-columns:1fr}}</style></head><body><div class="checkout-wrap"><a href="cart.html">← Back to cart</a><h1>Checkout</h1><p>Complete your delivery details. Prices and stock are verified on the server.</p><div id="checkoutError" role="alert"></div><div class="checkout-grid"><section class="checkout-card"><h2>Delivery Details</h2><form id="checkoutForm" method="post" action="create_order.php"><label>First name</label><input name="first_name" required value="<?=htmlspecialchars($user['first_name'],ENT_QUOTES)?>"><label>Last name</label><input name="last_name" required value="<?=htmlspecialchars($user['last_name'],ENT_QUOTES)?>"><label>Email</label><input name="email" type="email" required value="<?=htmlspecialchars($user['email'],ENT_QUOTES)?>"><label>Phone</label><input name="phone" required value="<?=htmlspecialchars($user['phone']??'',ENT_QUOTES)?>"><label>Delivery address</label><textarea name="address" required rows="3"><?=htmlspecialchars($addr,ENT_QUOTES)?></textarea><label>City</label><input name="city" required><input type="hidden" name="cart_json" id="cartJson"><button class="btn btn-primary" type="submit">Continue to PayHere Sandbox</button></form></section><section class="checkout-card"><h2>Order Summary</h2><div id="checkoutItems">Loading cart…</div>                  </section></div></div><script>
