const box=document.getElementById('checkoutItems');if(!cart.length){box.textContent='Your cart is empty.';document.querySelector('#checkoutForm button').disabled=true;}else{box.innerHTML=cart.map(x=>`<p>${String(x.name).replace(/[&<>"]/g,'')} × ${Number(x.qty)||1} — LKR ${(Number(x.price)*(Number(x.qty)||1)).toLocaleString()}</p>`).join('');}
